  const reducedRt = laneProfileRoadType(mainRt, { lanesPerSide: reducedLanesPerSide });
  const { rhw: reducedHalfW } = roadHalfWidth(reducedRt.hubMul);
  const laneProfile = { lanesPerSide: reducedLanesPerSide };
