  const ix = Math.max(0, Math.min(TERRAIN_CELLS - 1, Math.floor(gx))), iz = Math.max(0, Math.min(TERRAIN_CELLS - 1, Math.floor(gz)));
  const fx = Math.max(0, Math.min(1, gx - ix)), fz = Math.max(0, Math.min(1, gz - iz));
