    cargo: { len: 0.46, wid: 0.26, h: 0.24, offZ: -0.16, yAdd: 0.12 },
    wheel: { r: 0.38, w: 0.22, offsets: [[0.84, 1.30], [0.84, -1.65], [-0.84, 1.30], [-0.84, -1.65]] },
