      pushSupportQuad(positions, aLb, bLb, bL, aL); // underside
      pushSupportQuad(positions, aL, bL, bR, aR);   // top (against slab)
      pushSupportQuad(positions, aR, bR, bRb, aRb); // side
      pushSupportQuad(positions, bL, aL, aLb, bLb); // side
