      const aR = { x: A.p.x - A.n.x * w, y: yA, z: A.p.z - A.n.z * w };
      const bL = { x: B.p.x + B.n.x * w, y: yB, z: B.p.z + B.n.z * w };
      const bR = { x: B.p.x - B.n.x * w, y: yB, z: B.p.z - B.n.z * w };
