      const p2 = { x: pt.p.x - pt.n.x * w, y: bottom, z: pt.p.z - pt.n.z * w };
      const p3 = { x: p2.x, y: top, z: p2.z };
      const p4 = { x: p1.x, y: top, z: p1.z };
