        const ax1 = A.p.x + A.n.x * aOut * sign, az1 = A.p.z + A.n.z * aOut * sign;
        const bx0 = B.p.x + B.n.x * aIn * sign, bz0 = B.p.z + B.n.z * aIn * sign;
        const bx1 = B.p.x + B.n.x * aOut * sign, bz1 = B.p.z + B.n.z * aOut * sign;
